def mod_details_fallback(
    code: str, key: str, existing: dict[str, str]
) -> str | None:
    """Compose the compact Mod Details vocabulary from reviewed translations.

    The screen deliberately reuses the same native menu language as MODS,
    Loader Settings, and Mod Config.  Building these labels from the shipped
    locale's existing phrases keeps all 16 catalogs translated without
    introducing a second, drifting set of technical terminology.
    """
    common = {
        "DLUMA_Common_Unavailable": "DLUMA_Mods_State_Incompatible",
        "DLUMA_ModDetails_Title": "DLUMA_Common_Details",
        "DLUMA_ModDetails_NotApplicable": "DLUMA_Common_None",
        "DLUMA_ModDetails_Category_Overview": "DLUMA_Common_Details",
        "DLUMA_ModDetails_Category_State": "DLUMA_Common_State",
        "DLUMA_ModDetails_Category_Security": "DLUMA_Common_Risk",
        "DLUMA_ModDetails_Category_Config": "DLUMA_ModConfig_Title",
        "DLUMA_ModDetails_SelectField": "DLUMA_Common_Select",
        "DLUMA_ModDetails_SelectFieldHint": "DLUMA_Settings_SelectSetting",
        "DLUMA_ModDetails_SeenRecorded": "DLUMA_ModConfig_Saved",
    }
    source_key = common.get(key)
    if source_key:
        return existing.get(source_key)
    if key in {"DLUMA_ModDetails_Stale", "DLUMA_ModDetails_OpenFailed"}:
        details = existing.get("DLUMA_Common_Details")
        unavailable = existing.get("DLUMA_Mods_State_Incompatible")
        if details and unavailable:
            return f"{details}: {unavailable}"
    if key == "DLUMA_ModDetails_SeenFailed":
        details = existing.get("DLUMA_Common_Details")
        error = existing.get("DLUMA_Common_Error")
        if details and error:
            return f"{details}: {error}"
    return None


