def translate(
    code: str, key: str, value: str, existing: dict[str, str]
) -> str:
    if key in AUTO_ENABLE_KEYS:
        return AUTO_ENABLE_TEXT[code][AUTO_ENABLE_KEYS.index(key)]
    if key in ASSET_MOD_KEYS:
        return ASSET_MOD_TEXT[code][ASSET_MOD_KEYS.index(key)]
    if key in LOG_KEYS:
        return LOG_TEXT[code][LOG_KEYS.index(key)]
    details_text = mod_details_fallback(code, key, existing)
    if details_text:
        return details_text
    if key == "DLUMA_NewModsPopup_Mod":
        labels = {"Cn":"模组：{name}","Tw":"模組：{name}","Jp":"MOD: {name}","Ko":"모드: {name}"}
        return labels.get(code, "Nome mod: {name}" if code == "It" else SHORT[code]["Mods"] + ": {name}")
    if key in SETTING_TEXT.get(code, {}): return SETTING_TEXT[code][key]
    if key in FIXED.get(code, {}): return FIXED[code][key]
    if code in RUNTIME_TEMPLATES and key in runtime_map(code): return runtime_map(code)[key]
    if code in RUNTIME_WORDS:
        text = runtime_extra(code, key)
        if text: return text
    if re.fullmatch(r"DLUMA_Crash_Title_(\d\d)", key): return TITLES[code][int(key[-2:]) - 1]
    if value in SHORT.get(code, {}): return SHORT[code][value]
    if value in {"ID", "Version"}: return value
    if key.startswith("DLUMA_Settings_"):
        text = setting_fallback(code, key)
        if text: return text
    # The remaining keys are common settings strings whose translation is
    # supplied by the compact locale-specific category tables above.
    if code != "De":
        n = SETTING_NAMES[code]
        if value == "Edit value": return SHORT[code][value]
        if value == "Saved. The new value will apply after restarting the loader.": return n["restart"]
    raise KeyError(f"No translation for {code}:{key} ({value})")


def sync_log_catalogs() -> int:
    for code in LOCALES:
        path = LOCALE_ROOT / code / "loader_texts_all.scr"
        text = path.read_text(encoding="utf-8-sig")
        missing = [key for key in LOG_KEYS if f'String("{key}",' not in text]
        if not missing:
            continue
        if len(missing) != len(LOG_KEYS) and missing != ["DLUMA_Logs_SearchEditing"]:
            raise ValueError(f"{code} has a partial Logs localization block")
        values = dict(zip(LOG_KEYS, LOG_TEXT[code], strict=True))
        block = ["", "// LOGS" if len(missing) == len(LOG_KEYS) else "// LOGS SEARCH EDITING"]
        block.extend(
            f'String("{key}", "{q(values[key])}")'
            for key in missing
        )
        normalized = text.replace("\r\n", "\n").replace("\r", "\n").rstrip("\n")
        path.write_text(
            normalized + "\r\n" + "\r\n".join(block) + "\r\n",
            encoding="utf-8",
            newline="",
        )
    return 0


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--logs-only", action="store_true",
        help="append the reviewed Logs vocabulary without rewriting existing catalogs",
    )
    args = parser.parse_args()
    if args.logs_only:
        return sync_log_catalogs()

    from compile_localized_scr import parse_scr

    english = parse_scr(LOCALE_ROOT / "En" / "loader_texts_all.scr")
    for code in LOCALES:
        path = LOCALE_ROOT / code / "loader_texts_all.scr"
        existing = parse_scr(path)
        values: dict[str, str] = {}
        for key, value in english.items():
            # Preserve existing specific translations. Generic fallback tables
            # are useful for new entries but must not replace reviewed text.
            if key in existing and key not in AUTO_ENABLE_KEYS:
                values[key] = existing[key]
                continue
            try:
                values[key] = translate(code, key, value, existing)
            except KeyError:
                translated = existing.get(key)
                if translated is None:
                    raise
                values[key] = translated
        lines = ["!String(s, s)", "", f"// {code} loader localization"]
        lines.extend(f'String("{key}", "{q(values[key])}")' for key in english)
        path.write_text("\r\n".join(lines) + "\r\n", encoding="utf-8", newline="")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
